-- Baseline schema.
--
-- Generated by pg_dump from a local Supabase database, limited to what the
-- project's migrations create: the public and shipbash_private schemas with
-- their tables, functions, triggers, row-level security, policies and
-- privileges, followed by the two Storage buckets the app uploads to.
--
-- Objects the Supabase platform provides are not created here: the auth and
-- storage schemas (auth.users, auth.identities, storage.buckets, auth.uid()),
-- the extensions, and the default privileges on the public schema.
--
-- Every name below is schema-qualified, so pg_dump's session settings are left
-- out: a setting such as search_path would outlive this file in the session
-- that applies it. The one exception is check_function_bodies, off from here
-- to the matching reset after the last object, because pg_dump creates
-- functions before the tables their bodies name.

set check_function_bodies = off;

--
-- Name: SCHEMA public; Type: COMMENT; Schema: -; Owner: pg_database_owner
--

COMMENT ON SCHEMA public IS 'ShipBash control-plane data. Browser clients have no direct table access; all access goes through the server.';

--
-- Name: shipbash_private; Type: SCHEMA; Schema: -; Owner: postgres
--

CREATE SCHEMA shipbash_private;

ALTER SCHEMA shipbash_private OWNER TO postgres;

--
-- Name: SCHEMA shipbash_private; Type: COMMENT; Schema: -; Owner: postgres
--

COMMENT ON SCHEMA shipbash_private IS 'Private ShipBash authorization and validation helpers. Not exposed through the public API.';

--
-- Name: shipbash_assign_project_slug(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.shipbash_assign_project_slug() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if nullif(btrim(coalesce(new.slug, '')), '') is null then
    new.slug := public.shipbash_project_slug(new.team_id, new.name);
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.shipbash_assign_project_slug() OWNER TO postgres;

--
-- Name: shipbash_assign_team_slug(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.shipbash_assign_team_slug() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if nullif(btrim(coalesce(new.slug, '')), '') is null then
    new.slug := public.shipbash_team_slug(new.name);
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.shipbash_assign_team_slug() OWNER TO postgres;

--
-- Name: shipbash_project_slug(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.shipbash_project_slug(scoped_team_id uuid, source text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  base text := coalesce(nullif(public.shipbash_slugify(source), ''), 'product');
  candidate text := base;
  suffix integer := 1;
begin
  -- Only unique inside its team: two teams may each have a `checkout`.
  while exists (
    select 1 from public.projects
    where team_id = scoped_team_id and slug = candidate
  )
  loop
    suffix := suffix + 1;
    candidate := base || '-' || suffix;
  end loop;
  return candidate;
end;
$$;

ALTER FUNCTION public.shipbash_project_slug(scoped_team_id uuid, source text) OWNER TO postgres;

--
-- Name: shipbash_reserved_slug(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.shipbash_reserved_slug(candidate text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select candidate in (
    'access', 'api', 'auth', 'login', 'logout', 'invitations', 'internal', 'local',
    'browser', 'design-fixtures', 'icon', 'manifest', 'well-known', 'static',
    'public', 'waitlist'
  );
$$;

ALTER FUNCTION public.shipbash_reserved_slug(candidate text) OWNER TO postgres;

--
-- Name: shipbash_slugify(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.shipbash_slugify(source text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- Lowercase, keep letters and digits, collapse everything else to a single
  -- dash, and trim the dashes off the ends. An empty result is the caller's
  -- problem to fall back on, not this function's to invent.
  select trim(both '-' from regexp_replace(lower(coalesce(source, '')), '[^a-z0-9]+', '-', 'g'));
$$;

ALTER FUNCTION public.shipbash_slugify(source text) OWNER TO postgres;

--
-- Name: shipbash_team_slug(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.shipbash_team_slug(source text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  base text := coalesce(nullif(public.shipbash_slugify(source), ''), 'team');
  candidate text := base;
  suffix integer := 1;
begin
  while public.shipbash_reserved_slug(candidate)
    or exists (select 1 from public.teams where slug = candidate)
  loop
    suffix := suffix + 1;
    candidate := base || '-' || suffix;
  end loop;
  return candidate;
end;
$$;

ALTER FUNCTION public.shipbash_team_slug(source text) OWNER TO postgres;

--
-- Name: accept_team_invitation(text); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.accept_team_invitation(invitation_token_hash text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor_id uuid := auth.uid();
  actor_github_user_id bigint;
  invitation public.team_invitations%rowtype;
begin
  if actor_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if invitation_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid invitation token' using errcode = '22023';
  end if;

  select github_user_id into actor_github_user_id
  from public.user_profiles
  where user_id = actor_id;
  if actor_github_user_id is null then
    raise exception 'verified GitHub profile required' using errcode = '42501';
  end if;

  select * into invitation
  from public.team_invitations
  where token_hash = invitation_token_hash
  for update;

  if invitation.id is null
    or invitation.status <> 'pending'
    or invitation.expires_at <= clock_timestamp()
    or invitation.invited_github_user_id <> actor_github_user_id then
    raise exception 'invitation is invalid, expired, consumed, or belongs to another user'
      using errcode = '42501';
  end if;

  insert into public.team_memberships (team_id, user_id, role)
  values (invitation.team_id, actor_id, 'member')
  on conflict (team_id, user_id) do nothing;

  perform shipbash_private.grant_membership(actor_id);

  update public.team_invitations
  set status = 'accepted', accepted_by = actor_id, accepted_at = clock_timestamp()
  where id = invitation.id;

  return invitation.team_id;
end;
$_$;

ALTER FUNCTION shipbash_private.accept_team_invitation(invitation_token_hash text) OWNER TO postgres;

--
-- Name: bootstrap_current_user(text); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.bootstrap_current_user(display_name_override text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor_id uuid := auth.uid();
  actor_email text;
  github_payload jsonb;
  google_payload jsonb;
  verified_github_id_text text;
  verified_github_id bigint;
  verified_github_login text;
  verified_workspace_domain text;
  previous_workspace_domain text;
  requested_display_name text;
  effective_display_name text;
  landing_team_id uuid;
begin
  if actor_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select nullif(btrim(account.email), '') into actor_email
  from auth.users account where account.id = actor_id for update;
  if not found then
    raise exception 'authenticated user not found' using errcode = '42501';
  end if;

  select identity.identity_data into github_payload
  from auth.identities identity
  where identity.user_id = actor_id and identity.provider = 'github'
  limit 1;
  select identity.identity_data into google_payload
  from auth.identities identity
  where identity.user_id = actor_id and identity.provider = 'google'
  limit 1;
  if github_payload is null and google_payload is null then
    raise exception 'verified GitHub or Google identity required' using errcode = '42501';
  end if;

  if github_payload is not null then
    verified_github_id_text := coalesce(
      github_payload ->> 'provider_id',
      github_payload ->> 'sub',
      github_payload ->> 'id'
    );
    verified_github_login := coalesce(
      nullif(btrim(github_payload ->> 'user_name'), ''),
      nullif(btrim(github_payload ->> 'preferred_username'), ''),
      nullif(btrim(github_payload ->> 'login'), '')
    );
    if verified_github_id_text is null
      or verified_github_id_text !~ '^[0-9]+$'
      or verified_github_login is null then
      raise exception 'verified GitHub identity required' using errcode = '42501';
    end if;
    verified_github_id := verified_github_id_text::bigint;
    if verified_github_id <= 0 or length(verified_github_login) > 100 then
      raise exception 'verified GitHub identity is invalid' using errcode = '22023';
    end if;
  end if;

  -- A domain in a shape a team cannot hold is no Workspace domain to act on.
  verified_workspace_domain := lower(btrim(google_payload -> 'custom_claims' ->> 'hd'));
  if verified_workspace_domain !~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$' then
    verified_workspace_domain := null;
  end if;

  requested_display_name := nullif(btrim(display_name_override), '');
  if requested_display_name is not null and length(requested_display_name) > 120 then
    raise exception 'display name must contain at most 120 characters' using errcode = '22023';
  end if;
  effective_display_name := left(coalesce(
    requested_display_name,
    nullif(btrim(github_payload ->> 'full_name'), ''),
    nullif(btrim(github_payload ->> 'name'), ''),
    verified_github_login,
    nullif(btrim(google_payload ->> 'full_name'), ''),
    nullif(btrim(google_payload ->> 'name'), ''),
    split_part(actor_email, '@', 1)
  ), 120);

  select profile.workspace_domain into previous_workspace_domain
  from public.user_profiles profile where profile.user_id = actor_id;

  insert into public.user_profiles (
    user_id, display_name, github_user_id, github_login, avatar_url, email, workspace_domain
  ) values (
    actor_id,
    effective_display_name,
    verified_github_id,
    verified_github_login,
    coalesce(
      nullif(btrim(github_payload ->> 'avatar_url'), ''),
      nullif(btrim(google_payload ->> 'avatar_url'), ''),
      nullif(btrim(google_payload ->> 'picture'), '')
    ),
    case when verified_github_id is null then actor_email end,
    verified_workspace_domain
  )
  on conflict (user_id) do update
  set
    display_name = coalesce(requested_display_name, public.user_profiles.display_name),
    github_user_id = excluded.github_user_id,
    github_login = excluded.github_login,
    avatar_url = excluded.avatar_url,
    email = excluded.email,
    workspace_domain = excluded.workspace_domain,
    updated_at = now();

  -- An account in no team is a new one, and gets its own team.
  if not exists (select 1 from public.team_memberships where user_id = actor_id) then
    insert into public.teams (name, created_by)
    values (left(effective_display_name || '''s Team', 120), actor_id)
    returning id into landing_team_id;
    insert into public.team_memberships (team_id, user_id, role)
    values (landing_team_id, actor_id, 'admin');
  end if;

  -- Only when the account's Workspace domain first appears, so someone an
  -- admin removed from the company team is not put back by the next sign-in.
  if verified_workspace_domain is distinct from previous_workspace_domain
    and verified_workspace_domain is not null then
    landing_team_id := shipbash_private.join_company_team(actor_id, verified_workspace_domain);
  end if;

  if landing_team_id is not null then
    update public.user_profiles set default_team_id = landing_team_id where user_id = actor_id;
  end if;
end;
$_$;

ALTER FUNCTION shipbash_private.bootstrap_current_user(display_name_override text) OWNER TO postgres;

--
-- Name: can_view_profile(uuid); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.can_view_profile(target_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    target_user_id = (select auth.uid())
    or exists (
      select 1
      from public.team_memberships viewer
      join public.team_memberships target on target.team_id = viewer.team_id
      where viewer.user_id = (select auth.uid())
        and target.user_id = target_user_id
    );
$$;

ALTER FUNCTION shipbash_private.can_view_profile(target_user_id uuid) OWNER TO postgres;

--
-- Name: grant_membership(uuid); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.grant_membership(member_user_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update auth.users
  set raw_app_meta_data =
    coalesce(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object('shipbash_member', true)
  where id = member_user_id;
$$;

ALTER FUNCTION shipbash_private.grant_membership(member_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION grant_membership(member_user_id uuid); Type: COMMENT; Schema: shipbash_private; Owner: postgres
--

COMMENT ON FUNCTION shipbash_private.grant_membership(member_user_id uuid) IS 'Marks an account as let in. Read by the console proxy from the session user''s app_metadata.';

--
-- Name: invalidate_sign_in_authenticator(); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.invalidate_sign_in_authenticator() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.status = 'revoked' or old.github_account_login is distinct from new.github_account_login then
    delete from public.sign_in_authenticators where sign_in_id = new.id;
  end if;
  return new;
end;
$$;

ALTER FUNCTION shipbash_private.invalidate_sign_in_authenticator() OWNER TO postgres;

--
-- Name: is_team_member(uuid); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.is_team_member(target_team_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.team_memberships membership
    where membership.team_id = target_team_id
      and membership.user_id = (select auth.uid())
  );
$$;

ALTER FUNCTION shipbash_private.is_team_member(target_team_id uuid) OWNER TO postgres;

--
-- Name: join_company_team(uuid, text); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.join_company_team(actor_id uuid, domain text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  company_team_id uuid;
  company_admitted boolean;
begin
  insert into public.teams (name, created_by, workspace_domain)
  values (upper(left(split_part(domain, '.', 1), 1)) || substr(split_part(domain, '.', 1), 2), actor_id, domain)
  on conflict (workspace_domain) do nothing
  returning id into company_team_id;
  if company_team_id is not null then
    insert into public.team_memberships (team_id, user_id, role)
    values (company_team_id, actor_id, 'admin');
    return company_team_id;
  end if;

  select team.id into company_team_id from public.teams team where team.workspace_domain = domain;
  -- A team someone of the company was already let into vouches for the rest
  -- of it, the way an accepted invitation does.
  select exists (
    select 1
    from public.team_memberships membership
    join auth.users account on account.id = membership.user_id
    where membership.team_id = company_team_id
      and (account.raw_app_meta_data ->> 'shipbash_member')::boolean
  ) into company_admitted;
  insert into public.team_memberships (team_id, user_id, role)
  values (company_team_id, actor_id, 'member')
  on conflict (team_id, user_id) do nothing;
  if company_admitted then
    perform shipbash_private.grant_membership(actor_id);
  end if;
  return company_team_id;
end;
$$;

ALTER FUNCTION shipbash_private.join_company_team(actor_id uuid, domain text) OWNER TO postgres;

--
-- Name: remove_team_member(uuid, uuid); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.remove_team_member(target_team_id uuid, target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  existing_membership_role text;
  admin_count integer;
begin
  if actor_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  perform 1 from public.teams where id = target_team_id for update;
  if not found then
    raise exception 'team not found' using errcode = 'P0002';
  end if;
  if not exists (
    select 1 from public.team_memberships
    where team_id = target_team_id and user_id = actor_id and role = 'admin'
  ) then
    raise exception 'team admin required' using errcode = '42501';
  end if;

  select membership.role into existing_membership_role
  from public.team_memberships membership
  where membership.team_id = target_team_id and membership.user_id = target_user_id
  for update;
  if existing_membership_role is null then
    raise exception 'team membership not found' using errcode = 'P0002';
  end if;

  if existing_membership_role = 'admin' then
    select count(*)::integer into admin_count
    from public.team_memberships
    where team_id = target_team_id and role = 'admin';
    if admin_count <= 1 then
      raise exception 'cannot remove the final team admin' using errcode = '23514';
    end if;
  end if;

  delete from public.team_memberships
  where team_id = target_team_id and user_id = target_user_id;
end;
$$;

ALTER FUNCTION shipbash_private.remove_team_member(target_team_id uuid, target_user_id uuid) OWNER TO postgres;

--
-- Name: set_team_member_role(uuid, uuid, text); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.set_team_member_role(target_team_id uuid, target_user_id uuid, target_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  existing_membership_role text;
  admin_count integer;
begin
  if actor_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if target_role not in ('admin', 'member') then
    raise exception 'invalid team role' using errcode = '22023';
  end if;

  perform 1 from public.teams where id = target_team_id for update;
  if not found then
    raise exception 'team not found' using errcode = 'P0002';
  end if;
  if not exists (
    select 1 from public.team_memberships
    where team_id = target_team_id and user_id = actor_id and role = 'admin'
  ) then
    raise exception 'team admin required' using errcode = '42501';
  end if;

  select membership.role into existing_membership_role
  from public.team_memberships membership
  where membership.team_id = target_team_id and membership.user_id = target_user_id
  for update;
  if existing_membership_role is null then
    raise exception 'team membership not found' using errcode = 'P0002';
  end if;

  if existing_membership_role = 'admin' and target_role = 'member' then
    select count(*)::integer into admin_count
    from public.team_memberships
    where team_id = target_team_id and role = 'admin';
    if admin_count <= 1 then
      raise exception 'cannot demote the final team admin' using errcode = '23514';
    end if;
  end if;

  update public.team_memberships
  set role = target_role, updated_at = now()
  where team_id = target_team_id and user_id = target_user_id;
end;
$$;

ALTER FUNCTION shipbash_private.set_team_member_role(target_team_id uuid, target_user_id uuid, target_role text) OWNER TO postgres;

--
-- Name: valid_case_checklist(jsonb, boolean); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.valid_case_checklist(value jsonb, is_terminal boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select
    jsonb_typeof(value) = 'array'
    and (
      jsonb_array_length(value) = 0
      or jsonb_array_length(value) between 1 and 8
    )
    and not exists (
      select 1
      from jsonb_array_elements(value) as item
      where coalesce(jsonb_typeof(item), '') <> 'object'
        or item - array['id', 'goal', 'status', 'reason']::text[] <> '{}'::jsonb
        or coalesce(jsonb_typeof(item -> 'id'), '') <> 'string'
        or length(item ->> 'id') = 0
        or length(item ->> 'id') > 64
        or (item ->> 'id') !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'
        or coalesce(jsonb_typeof(item -> 'goal'), '') <> 'string'
        or length(btrim(item ->> 'goal')) = 0
        or length(item ->> 'goal') > 1000
        or coalesce(item ->> 'status', '') not in (
          'pending', 'in_progress', 'passed', 'failed', 'blocked', 'not_run'
        )
        or (
          item ? 'reason'
          and jsonb_typeof(item -> 'reason') not in ('string', 'null')
        )
        or (
          jsonb_typeof(item -> 'reason') = 'string'
          and (
            length(btrim(item ->> 'reason')) = 0
            or length(item ->> 'reason') > 300
            or coalesce(item ->> 'status', '') not in ('failed', 'blocked')
          )
        )
        or (
          is_terminal
          and coalesce(item ->> 'status', '') not in ('passed', 'failed', 'blocked', 'not_run')
        )
    )
    and (
      jsonb_array_length(value) = 0
      or (
        select count(distinct entry.item ->> 'id')
        from jsonb_array_elements(value) as entry(item)
      ) = jsonb_array_length(value)
    );
$_$;

ALTER FUNCTION shipbash_private.valid_case_checklist(value jsonb, is_terminal boolean) OWNER TO postgres;

--
-- Name: FUNCTION valid_case_checklist(value jsonb, is_terminal boolean); Type: COMMENT; Schema: shipbash_private; Owner: postgres
--

COMMENT ON FUNCTION shipbash_private.valid_case_checklist(value jsonb, is_terminal boolean) IS 'A run Checklist: empty, or one to eight unique items. The count follows the Case checkpoints it is built from, so a single-checkpoint hook reports a single item.';

--
-- Name: valid_case_definition(jsonb); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.valid_case_definition(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select
    jsonb_typeof(value) = 'array'
    and not exists (
      select 1
      from jsonb_array_elements(value) as item
      where coalesce(jsonb_typeof(item), '') <> 'object'
        or coalesce(jsonb_typeof(item -> 'title'), '') <> 'string'
        or length(btrim(item ->> 'title')) = 0
        or length(item ->> 'title') > 500
        or not shipbash_private.valid_journey_steps(item -> 'steps')
        or coalesce(item ->> 'enabled', 'true') not in ('true', 'false')
        or coalesce(jsonb_typeof(item -> 'category'), '') <> 'string'
        or length(btrim(item ->> 'category')) not between 1 and 120
        or not shipbash_private.valid_journey_checkpoints(item -> 'checkpoints')
        or (
          item ? 'whyItMatters'
          and jsonb_typeof(item -> 'whyItMatters') not in ('string', 'null')
        )
        or (
          jsonb_typeof(item -> 'whyItMatters') = 'string'
          and length(btrim(item ->> 'whyItMatters')) not between 1 and 300
        )
        or (
          item ? 'role'
          and coalesce(item ->> 'role', '') not in ('journey', 'before_all', 'after_all', 'before_each', 'after_each')
        )
        or (
          item ? 'scopeCaseId'
          and jsonb_typeof(item -> 'scopeCaseId') not in ('string', 'null')
        )
        or (
          item ? 'repeat'
          and coalesce(item ->> 'repeat', '') not in ('repeatable', 'one_time')
        )
    );
$$;

ALTER FUNCTION shipbash_private.valid_case_definition(value jsonb) OWNER TO postgres;

--
-- Name: valid_journey_checkpoints(jsonb); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.valid_journey_checkpoints(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select
    jsonb_typeof(value) = 'array'
    and jsonb_array_length(value) between 1 and 8
    and not exists (
      select 1
      from jsonb_array_elements(value) as checkpoint
      where jsonb_typeof(checkpoint) <> 'object'
        or checkpoint - array['id', 'goal', 'afterStep']::text[] <> '{}'::jsonb
        or coalesce(jsonb_typeof(checkpoint -> 'id'), '') <> 'string'
        or (checkpoint ->> 'id') !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'
        or coalesce(jsonb_typeof(checkpoint -> 'goal'), '') <> 'string'
        or length(btrim(checkpoint ->> 'goal')) not between 1 and 1000
        or (
          checkpoint ? 'afterStep'
          and jsonb_typeof(checkpoint -> 'afterStep') not in ('string', 'null')
        )
        or (
          jsonb_typeof(checkpoint -> 'afterStep') = 'string'
          and (checkpoint ->> 'afterStep') !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'
        )
    )
    and (
      select count(distinct checkpoint ->> 'id')
      from jsonb_array_elements(value) as checkpoint
    ) = jsonb_array_length(value);
$_$;

ALTER FUNCTION shipbash_private.valid_journey_checkpoints(value jsonb) OWNER TO postgres;

--
-- Name: FUNCTION valid_journey_checkpoints(value jsonb); Type: COMMENT; Schema: shipbash_private; Owner: postgres
--

COMMENT ON FUNCTION shipbash_private.valid_journey_checkpoints(value jsonb) IS 'Stored {id, goal, afterStep} checkpoints: one to eight, unique ids. The per-role minimum (a journey needs two) is applied where the Case role is known.';

--
-- Name: valid_journey_steps(jsonb); Type: FUNCTION; Schema: shipbash_private; Owner: postgres
--

CREATE FUNCTION shipbash_private.valid_journey_steps(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select
    jsonb_typeof(value) = 'array'
    and jsonb_array_length(value) between 1 and 100
    and not exists (
      select 1
      from jsonb_array_elements(value) as step
      where jsonb_typeof(step) <> 'object'
        or step - array['id', 'instruction']::text[] <> '{}'::jsonb
        or coalesce(jsonb_typeof(step -> 'id'), '') <> 'string'
        or (step ->> 'id') !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'
        or coalesce(jsonb_typeof(step -> 'instruction'), '') <> 'string'
        or length(btrim(step ->> 'instruction')) not between 1 and 20000
    )
    and (
      select count(distinct step ->> 'id')
      from jsonb_array_elements(value) as step
    ) = jsonb_array_length(value);
$_$;

ALTER FUNCTION shipbash_private.valid_journey_steps(value jsonb) OWNER TO postgres;

