    source_activity_id uuid,
    generation integer DEFAULT 1 NOT NULL,
    repository_id uuid,
    repository_commit_sha text,
    prompt_contract_version text NOT NULL,
    model_contract jsonb DEFAULT '{}'::jsonb NOT NULL,
    next_event_sequence bigint DEFAULT 1 NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    wrap_up_requested_at timestamp with time zone,
    source_proposal_id uuid,
    CONSTRAINT activities_check CHECK (((status = ANY (ARRAY['completed'::text, 'needs_attention'::text, 'failed'::text, 'canceled'::text, 'superseded'::text])) = (completed_at IS NOT NULL))),
    CONSTRAINT activities_check1 CHECK (((source_activity_id IS NULL) OR (generation > 1))),
    CONSTRAINT activities_generation_check CHECK ((generation >= 1)),
    CONSTRAINT activities_kind_check CHECK ((kind = ANY (ARRAY['initial_discovery'::text, 'generate_cases'::text, 'conversation'::text, 'walk'::text]))),
    CONSTRAINT activities_model_contract_check CHECK ((jsonb_typeof(model_contract) = 'object'::text)),
    CONSTRAINT activities_next_event_sequence_check CHECK ((next_event_sequence >= 1)),
    CONSTRAINT activities_prompt_contract_version_check CHECK ((length(btrim(prompt_contract_version)) > 0)),
    CONSTRAINT activities_protected_input_check CHECK (((protected_input IS NULL) OR (length(protected_input) <= 20000))),
    CONSTRAINT activities_repository_commit_sha_check CHECK (((repository_commit_sha IS NULL) OR (repository_commit_sha ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT activities_status_check CHECK ((status = ANY (ARRAY['debouncing'::text, 'queued'::text, 'running'::text, 'waiting_for_auth'::text, 'waiting_for_input'::text, 'completed'::text, 'needs_attention'::text, 'failed'::text, 'canceled'::text, 'superseded'::text]))),
    CONSTRAINT activities_trigger_source_check CHECK ((trigger_source = ANY (ARRAY['web'::text, 'cli'::text, 'webhook'::text, 'schedule'::text, 'retry'::text, 'slack'::text])))
);

