--

CREATE TABLE public.browser_recordings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    project_id text NOT NULL,
    case_run_id text NOT NULL,
    bucket_id text DEFAULT 'shipbash-browser-recordings'::text NOT NULL,
    object_path text,
    poster_object_path text,
    mime_type text,
    size_bytes bigint,
    width integer,
    height integer,
    duration_ms bigint,
    storage_status text DEFAULT 'pending'::text NOT NULL,
    storage_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    playback_metadata jsonb DEFAULT '{"cues": [], "anchors": [], "pointers": [], "terminal": [], "attention": [], "schemaVersion": 4, "speedSegments": []}'::jsonb NOT NULL,
    CONSTRAINT browser_recordings_bucket_id_check CHECK ((bucket_id = 'shipbash-browser-recordings'::text)),
    CONSTRAINT browser_recordings_check CHECK (((storage_status <> 'available'::text) OR ((object_path IS NOT NULL) AND (mime_type IS NOT NULL) AND (size_bytes IS NOT NULL) AND (width IS NOT NULL) AND (height IS NOT NULL) AND (duration_ms IS NOT NULL)))),
    CONSTRAINT browser_recordings_duration_ms_check CHECK (((duration_ms IS NULL) OR (duration_ms > 0))),
    CONSTRAINT browser_recordings_height_check CHECK (((height IS NULL) OR (height > 0))),
    CONSTRAINT browser_recordings_mime_type_check CHECK (((mime_type IS NULL) OR (mime_type = ANY (ARRAY['video/mp4'::text, 'video/webm'::text])))),
    CONSTRAINT browser_recordings_playback_metadata_check CHECK (((jsonb_typeof(playback_metadata) = 'object'::text) AND ((playback_metadata ->> 'schemaVersion'::text) = '4'::text) AND (NOT (jsonb_typeof((playback_metadata -> 'anchors'::text)) IS DISTINCT FROM 'array'::text)) AND (jsonb_array_length((playback_metadata -> 'anchors'::text)) <= 16) AND (NOT (jsonb_typeof((playback_metadata -> 'cues'::text)) IS DISTINCT FROM 'array'::text)) AND (jsonb_array_length((playback_metadata -> 'cues'::text)) <= 64) AND (NOT (jsonb_typeof((playback_metadata -> 'speedSegments'::text)) IS DISTINCT FROM 'array'::text)) AND (jsonb_array_length((playback_metadata -> 'speedSegments'::text)) <= 128) AND (NOT (jsonb_typeof((playback_metadata -> 'pointers'::text)) IS DISTINCT FROM 'array'::text)) AND (jsonb_array_length((playback_metadata -> 'pointers'::text)) <= 600) AND (NOT (jsonb_typeof((playback_metadata -> 'attention'::text)) IS DISTINCT FROM 'array'::text)) AND (jsonb_array_length((playback_metadata -> 'attention'::text)) <= 128) AND (NOT (jsonb_typeof((playback_metadata -> 'terminal'::text)) IS DISTINCT FROM 'array'::text)) AND (jsonb_array_length((playback_metadata -> 'terminal'::text)) <= 16))),
    CONSTRAINT browser_recordings_size_bytes_check CHECK (((size_bytes IS NULL) OR (size_bytes >= 0))),
    CONSTRAINT browser_recordings_storage_error_check CHECK (((storage_error IS NULL) OR (length(storage_error) <= 1000))),
    CONSTRAINT browser_recordings_storage_status_check CHECK ((storage_status = ANY (ARRAY['pending'::text, 'available'::text, 'failed'::text]))),
    CONSTRAINT browser_recordings_width_check CHECK (((width IS NULL) OR (width > 0)))
);

