    summary text,
    failure_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    team_id uuid,
    checklist jsonb DEFAULT '[]'::jsonb NOT NULL,
    reproduced_runs integer DEFAULT 1 NOT NULL,
    code_evidence jsonb,
    role text DEFAULT 'journey'::text NOT NULL,
    walk_ms integer,
    journey_case_id text,
    CONSTRAINT case_runs_attempt_check CHECK ((attempt >= 1)),
    CONSTRAINT case_runs_check CHECK ((((status = 'canceled'::text) AND (verdict = 'canceled'::text)) OR ((status = 'completed'::text) AND (verdict = ANY (ARRAY['passed'::text, 'failed'::text, 'blocked'::text, 'error'::text, 'exempted'::text, 'not_run'::text]))) OR ((status <> ALL (ARRAY['canceled'::text, 'completed'::text])) AND (verdict IS NULL)))),
    CONSTRAINT case_runs_check1 CHECK (((status = ANY (ARRAY['canceled'::text, 'completed'::text])) = (completed_at IS NOT NULL))),
    CONSTRAINT case_runs_checklist_check CHECK (shipbash_private.valid_case_checklist(checklist, (status = ANY (ARRAY['completed'::text, 'canceled'::text])))),
    CONSTRAINT case_runs_id_check CHECK ((length(btrim(id)) > 0)),
    CONSTRAINT case_runs_journey_case_id_check CHECK (((journey_case_id IS NULL) OR (role = 'before_each'::text) OR (role = 'after_each'::text))),
    CONSTRAINT case_runs_position_nonnegative_check CHECK (("position" >= 0)),
    CONSTRAINT case_runs_reproduced_runs_check CHECK ((reproduced_runs = ANY (ARRAY[1, 2]))),
    CONSTRAINT case_runs_role_check CHECK ((role = ANY (ARRAY['journey'::text, 'before_all'::text, 'after_all'::text, 'before_each'::text, 'after_each'::text]))),
    CONSTRAINT case_runs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'waiting_for_auth'::text, 'canceled'::text, 'completed'::text]))),
    CONSTRAINT case_runs_verdict_check CHECK ((verdict = ANY (ARRAY['passed'::text, 'failed'::text, 'blocked'::text, 'error'::text, 'canceled'::text, 'exempted'::text, 'not_run'::text]))),
    CONSTRAINT case_runs_walk_ms_check CHECK ((walk_ms >= 0))
);

ALTER TABLE public.case_runs OWNER TO postgres;

