    CONSTRAINT dispatch_jobs_check CHECK ((((kind = 'suite_run'::text) AND (suite_run_id IS NOT NULL) AND (activity_id IS NULL)) OR ((kind = 'activity'::text) AND (activity_id IS NOT NULL) AND (suite_run_id IS NULL)))),
    CONSTRAINT dispatch_jobs_check1 CHECK ((((status = 'leased'::text) AND (lease_token IS NOT NULL) AND (lease_owner IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (leased_at IS NOT NULL) AND (heartbeat_at IS NOT NULL)) OR ((status <> 'leased'::text) AND (lease_token IS NULL) AND (lease_owner IS NULL) AND (lease_expires_at IS NULL) AND (leased_at IS NULL) AND (heartbeat_at IS NULL)))),
    CONSTRAINT dispatch_jobs_check2 CHECK (((status = ANY (ARRAY['completed'::text, 'failed'::text, 'canceled'::text])) = (completed_at IS NOT NULL))),
    CONSTRAINT dispatch_jobs_idempotency_key_check CHECK ((length(btrim(idempotency_key)) > 0)),
    CONSTRAINT dispatch_jobs_identity_hash_check CHECK ((identity_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT dispatch_jobs_kind_check CHECK ((kind = ANY (ARRAY['suite_run'::text, 'activity'::text]))),
    CONSTRAINT dispatch_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'leased'::text, 'waiting'::text, 'completed'::text, 'failed'::text, 'canceled'::text]))),
    CONSTRAINT dispatch_jobs_write_scope_check CHECK ((jsonb_typeof(write_scope) = 'object'::text))
);

