    proposed_suite_name text,
    candidate_definition jsonb NOT NULL,
    status text DEFAULT 'ready'::text NOT NULL,
    repository_commit_sha text,
    trigger jsonb DEFAULT '{}'::jsonb NOT NULL,
    prompt_contract_version text NOT NULL,
    created_by uuid,
    decided_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
