    decided_at timestamp with time zone,
    product_thesis text,
    keep_decision jsonb,
    CONSTRAINT proposals_base_definition_revision_check CHECK (((base_definition_revision IS NULL) OR (base_definition_revision >= 1))),
    CONSTRAINT proposals_candidate_definition_check CHECK (shipbash_private.valid_case_definition(candidate_definition)),
    CONSTRAINT proposals_check CHECK ((((kind = 'create_suite'::text) AND (target_suite_id IS NULL) AND (base_definition_revision IS NULL) AND (proposed_suite_name IS NOT NULL)) OR ((kind = 'change_suite'::text) AND (target_suite_id IS NOT NULL) AND (base_definition_revision IS NOT NULL)))),
    CONSTRAINT proposals_check1 CHECK (((status = ANY (ARRAY['accepted'::text, 'rejected'::text, 'superseded'::text])) = (decided_at IS NOT NULL))),
    CONSTRAINT proposals_check2 CHECK (((status = 'accepted'::text) = (applied_suite_id IS NOT NULL))),
    CONSTRAINT proposals_kind_check CHECK ((kind = ANY (ARRAY['create_suite'::text, 'change_suite'::text]))),
    CONSTRAINT proposals_product_thesis_check CHECK (((product_thesis IS NULL) OR ((length(btrim(product_thesis)) >= 1) AND (length(btrim(product_thesis)) <= 600)))),
    CONSTRAINT proposals_prompt_contract_version_check CHECK ((length(btrim(prompt_contract_version)) > 0)),
    CONSTRAINT proposals_proposed_suite_name_check CHECK (((proposed_suite_name IS NULL) OR ((length(btrim(proposed_suite_name)) >= 1) AND (length(btrim(proposed_suite_name)) <= 200)))),
    CONSTRAINT proposals_repository_commit_sha_check CHECK (((repository_commit_sha IS NULL) OR (repository_commit_sha ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT proposals_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'ready'::text, 'accepted'::text, 'rejected'::text, 'superseded'::text]))),
    CONSTRAINT proposals_trigger_check CHECK ((jsonb_typeof(trigger) = 'object'::text))
);

