    resolved_at timestamp with time zone
);

ALTER TABLE public.run_auth_attention OWNER TO postgres;

--
-- Name: run_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.run_events (
    id text NOT NULL,
    suite_run_id text NOT NULL,
    case_run_id text,
    sequence bigint NOT NULL,
    type text NOT NULL,
    level text DEFAULT 'info'::text NOT NULL,
    message text NOT NULL,
    data jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    team_id uuid,
    project_id text,
    CONSTRAINT run_events_data_check CHECK (((data IS NULL) OR (jsonb_typeof(data) = 'object'::text))),
    CONSTRAINT run_events_id_check CHECK ((length(btrim(id)) > 0)),
    CONSTRAINT run_events_level_check CHECK ((level = ANY (ARRAY['info'::text, 'success'::text, 'warning'::text, 'error'::text]))),
    CONSTRAINT run_events_message_check CHECK ((length(btrim(message)) > 0)),
    CONSTRAINT run_events_sequence_check CHECK ((sequence >= 1)),
    CONSTRAINT run_events_type_check CHECK ((length(btrim(type)) > 0))
);

ALTER TABLE public.run_events OWNER TO postgres;

--
-- Name: runtime_sessions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.runtime_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    project_id text NOT NULL,
    source_kind text NOT NULL,
    source_id text NOT NULL,
    container_name text NOT NULL,
    control_directory text,
    auth_viewer_port integer,
    auth_viewer_url text,
    phase text DEFAULT 'starting'::text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    heartbeat_at timestamp with time zone DEFAULT now() NOT NULL,
    ended_at timestamp with time zone,
    end_reason text,
    CONSTRAINT runtime_sessions_auth_viewer_port_check CHECK (((auth_viewer_port IS NULL) OR ((auth_viewer_port >= 1) AND (auth_viewer_port <= 65535)))),
    CONSTRAINT runtime_sessions_auth_viewer_url_check CHECK (((auth_viewer_url IS NULL) OR (length(btrim(auth_viewer_url)) > 0))),
    CONSTRAINT runtime_sessions_container_name_check CHECK (((length(btrim(container_name)) >= 1) AND (length(btrim(container_name)) <= 255))),
    CONSTRAINT runtime_sessions_control_directory_check CHECK (((control_directory IS NULL) OR (length(btrim(control_directory)) > 0))),
    CONSTRAINT runtime_sessions_end_reason_check CHECK (((end_reason IS NULL) OR (length(end_reason) <= 500))),
    CONSTRAINT runtime_sessions_ended_at_matches_phase CHECK (((phase = 'ended'::text) = (ended_at IS NOT NULL))),
    CONSTRAINT runtime_sessions_phase_check CHECK ((phase = ANY (ARRAY['starting'::text, 'running'::text, 'waiting_for_auth'::text, 'waiting_for_input'::text, 'viewer'::text, 'ended'::text]))),
    CONSTRAINT runtime_sessions_source_id_check CHECK (((length(btrim(source_id)) >= 1) AND (length(btrim(source_id)) <= 128))),
    CONSTRAINT runtime_sessions_source_kind_check CHECK ((source_kind = ANY (ARRAY['activity'::text, 'suite_run'::text])))
);

ALTER TABLE public.runtime_sessions OWNER TO postgres;

--
-- Name: schedule_occurrences; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.schedule_occurrences (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    project_id text NOT NULL,
    suite_id uuid NOT NULL,
    schedule_id uuid NOT NULL,
    source_job_id uuid,
    scheduled_for timestamp with time zone NOT NULL,
    outcome text NOT NULL,
    suite_run_id text,
    reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT schedule_occurrences_check CHECK ((((outcome = 'dispatched'::text) AND (suite_run_id IS NOT NULL) AND (reason IS NULL)) OR ((outcome = 'skipped'::text) AND (suite_run_id IS NULL) AND (length(btrim(reason)) > 0)))),
    CONSTRAINT schedule_occurrences_outcome_check CHECK ((outcome = ANY (ARRAY['dispatched'::text, 'skipped'::text])))
);

ALTER TABLE public.schedule_occurrences OWNER TO postgres;

--
-- Name: sign_in_authenticators; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.sign_in_authenticators (
    sign_in_id uuid NOT NULL,
    team_id uuid NOT NULL,
    account_login text NOT NULL,
    secret_ciphertext text NOT NULL,
    encryption_key_id text NOT NULL,
    config_version uuid DEFAULT gen_random_uuid() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sign_in_authenticators_account_login_check CHECK ((account_login ~ '^[a-zA-Z0-9][a-zA-Z0-9-]{0,38}$'::text))
);

ALTER TABLE public.sign_in_authenticators OWNER TO postgres;

--
-- Name: sign_in_takeovers; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.sign_in_takeovers (
    project_id text NOT NULL,
    team_id uuid NOT NULL,
    control_token text NOT NULL,
    start_url text,
    sandbox_name text,
    command_id text,
    stream_url text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sign_in_takeovers_browser_check CHECK ((((sandbox_name IS NULL) = (command_id IS NULL)) AND ((sandbox_name IS NULL) = (stream_url IS NULL)))),
    CONSTRAINT sign_in_takeovers_command_id_check CHECK (((command_id IS NULL) OR (length(btrim(command_id)) > 0))),
    CONSTRAINT sign_in_takeovers_control_token_check CHECK ((control_token ~ '^[A-Za-z0-9_-]{43}$'::text)),
    CONSTRAINT sign_in_takeovers_sandbox_name_check CHECK (((sandbox_name IS NULL) OR (sandbox_name ~ '^shipbash-signin-[0-9a-f]{16}-[0-9a-f]{8}$'::text))),
    CONSTRAINT sign_in_takeovers_start_url_check CHECK (((start_url IS NULL) OR (length(btrim(start_url)) > 0))),
    CONSTRAINT sign_in_takeovers_stream_url_check CHECK (((stream_url IS NULL) OR (length(btrim(stream_url)) > 0)))
);

ALTER TABLE public.sign_in_takeovers OWNER TO postgres;

--
-- Name: TABLE sign_in_takeovers; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.sign_in_takeovers IS 'The one sign-in browser a Project drives by hand at a time on the hosted console: the control lease its canvas presents and, once the browser is up, the Sandbox, the command running it and the stream it shows. Service role only.';

--
-- Name: slack_alert_messages; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.slack_alert_messages (
    suite_run_id text NOT NULL,
    message_key text NOT NULL,
    team_id uuid NOT NULL,
    project_id text NOT NULL,
    channel_id text NOT NULL,
    thread_ts text,
    state text NOT NULL,
    message_ts text,
    attempted_at timestamp with time zone DEFAULT now() NOT NULL,
    settled_at timestamp with time zone,
    error text,
    CONSTRAINT slack_alert_messages_channel_id_check CHECK ((channel_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_alert_messages_error_check CHECK ((char_length(error) <= 2000)),
    CONSTRAINT slack_alert_messages_message_key_check CHECK (((char_length(message_key) >= 1) AND (char_length(message_key) <= 300))),
    CONSTRAINT slack_alert_messages_message_ts_check CHECK ((message_ts ~ '^[0-9]+\.[0-9]+$'::text)),
    CONSTRAINT slack_alert_messages_settled_check CHECK (((state = 'posting'::text) = (settled_at IS NULL))),
    CONSTRAINT slack_alert_messages_state_check CHECK ((state = ANY (ARRAY['posting'::text, 'sent'::text, 'failed'::text, 'unknown'::text]))),
    CONSTRAINT slack_alert_messages_thread_ts_check CHECK ((thread_ts ~ '^[0-9]+\.[0-9]+$'::text))
);

ALTER TABLE public.slack_alert_messages OWNER TO postgres;

--
-- Name: TABLE slack_alert_messages; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.slack_alert_messages IS 'One Slack message a run''s alert intends to post. A key that is sent or unknown is never posted again, which is what keeps a retried send from repeating itself in the channel.';

--
-- Name: slack_alert_outbox; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.slack_alert_outbox (
    suite_run_id text NOT NULL,
    team_id uuid NOT NULL,
    project_id text NOT NULL,
    enqueued_at timestamp with time zone DEFAULT now() NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    claimed_at timestamp with time zone,
    last_error text,
    status text DEFAULT 'pending'::text NOT NULL,
    settled_at timestamp with time zone,
    unannounced_reason text,
    alert_kind text,
    claim_id uuid,
    channel_id text NOT NULL,
    CONSTRAINT slack_alert_outbox_alert_kind_check CHECK (((alert_kind IS NULL) OR (alert_kind = ANY (ARRAY['failed'::text, 'could_not_verify'::text])))),
    CONSTRAINT slack_alert_outbox_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT slack_alert_outbox_channel_id_check CHECK ((channel_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_alert_outbox_last_error_check CHECK (((last_error IS NULL) OR (length(last_error) <= 2000))),
    CONSTRAINT slack_alert_outbox_settled_check CHECK (((status = 'pending'::text) = (settled_at IS NULL))),
    CONSTRAINT slack_alert_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sent'::text, 'unannounced'::text]))),
    CONSTRAINT slack_alert_outbox_unannounced_cause_check CHECK (((status = 'unannounced'::text) = (unannounced_reason IS NOT NULL))),
    CONSTRAINT slack_alert_outbox_unannounced_reason_check CHECK (((unannounced_reason IS NULL) OR (unannounced_reason = ANY (ARRAY['workspace_revoked'::text, 'binding_removed'::text, 'delivery_refused'::text]))))
);

ALTER TABLE public.slack_alert_outbox OWNER TO postgres;

--
-- Name: TABLE slack_alert_outbox; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.slack_alert_outbox IS 'One finished run''s alert into one channel, enqueued by the finalization transaction and sent outside it. A row exists because the run''s project was bound to that channel at the moment it finalized.';

--
-- Name: COLUMN slack_alert_outbox.alert_kind; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.slack_alert_outbox.alert_kind IS 'What the run had to announce, recorded whether or not it was announced. An unannounced row with ''failed'' is a product failure nobody heard about.';

--
-- Name: slack_alert_threads; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.slack_alert_threads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    project_id text NOT NULL,
    subject_kind text NOT NULL,
    subject text NOT NULL,
    channel_id text NOT NULL,
    thread_ts text NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    last_checkpoint text,
    closed_at timestamp with time zone,
    CONSTRAINT slack_alert_threads_channel_id_check CHECK ((channel_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_alert_threads_closed_check CHECK (((closed_at IS NULL) OR (closed_at >= opened_at))),
    CONSTRAINT slack_alert_threads_last_checkpoint_check CHECK (((last_checkpoint IS NULL) OR (length(last_checkpoint) <= 200))),
    CONSTRAINT slack_alert_threads_subject_check CHECK (((length(btrim(subject)) >= 1) AND (length(btrim(subject)) <= 200))),
    CONSTRAINT slack_alert_threads_subject_kind_check CHECK ((subject_kind = ANY (ARRAY['journey'::text, 'blocker'::text]))),
    CONSTRAINT slack_alert_threads_thread_ts_check CHECK ((thread_ts ~ '^[0-9]+\.[0-9]+$'::text))
);

ALTER TABLE public.slack_alert_threads OWNER TO postgres;

--
-- Name: TABLE slack_alert_threads; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.slack_alert_threads IS 'The Slack message a red subject is holding open. While a row is open every later result about that subject is a reply, which is what stops a journey that stays red from posting once per run.';

--
-- Name: slack_channel_bindings; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.slack_channel_bindings (
    project_id text NOT NULL,
    team_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    channel_id text NOT NULL,
    channel_name text NOT NULL,
    is_private boolean NOT NULL,
    bound_by uuid NOT NULL,
    bound_at timestamp with time zone DEFAULT now() NOT NULL,
    last_delivered_at timestamp with time zone,
    delivery_error text,
    CONSTRAINT slack_channel_bindings_channel_id_check CHECK ((channel_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_channel_bindings_channel_name_check CHECK (((length(btrim(channel_name)) >= 1) AND (length(btrim(channel_name)) <= 80))),
    CONSTRAINT slack_channel_bindings_delivery_error_check CHECK (((delivery_error IS NULL) OR (delivery_error = ANY (ARRAY['not_in_channel'::text, 'channel_not_found'::text, 'is_archived'::text, 'delivery_failed'::text]))))
);

ALTER TABLE public.slack_channel_bindings OWNER TO postgres;

--
-- Name: TABLE slack_channel_bindings; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.slack_channel_bindings IS 'One Slack channel a project alerts into, as an admin chose it; a project may have several, and a channel may serve several projects. Slack is asked about the channel before the row is written; whether a message has arrived since is last_delivered_at.';

--
-- Name: COLUMN slack_channel_bindings.last_delivered_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.slack_channel_bindings.last_delivered_at IS 'When a test or an alert last really arrived in this channel for this project; null until one has. A refused delivery never touches it.';

--
-- Name: COLUMN slack_channel_bindings.delivery_error; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.slack_channel_bindings.delivery_error IS 'Why the last delivery was refused, or null while the channel is accepting. An auth failure is not recorded here; it revokes the workspace.';

--
-- Name: slack_install_states; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.slack_install_states (
    state_hash text NOT NULL,
    team_id uuid NOT NULL,
    user_id uuid NOT NULL,
    return_path text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT slack_install_states_consumed_check CHECK (((consumed_at IS NULL) OR (consumed_at >= created_at))),
    CONSTRAINT slack_install_states_expiry_check CHECK ((expires_at > created_at)),
    CONSTRAINT slack_install_states_return_path_check CHECK (((return_path ~ '^/[A-Za-z0-9][A-Za-z0-9._~%/?=&-]*$'::text) AND (length(return_path) <= 1024))),
    CONSTRAINT slack_install_states_state_hash_check CHECK ((state_hash ~ '^[0-9a-f]{64}$'::text))
);

ALTER TABLE public.slack_install_states OWNER TO postgres;

--
-- Name: TABLE slack_install_states; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.slack_install_states IS 'One Slack install redirect in flight: only the state token''s hash is stored, and it is consumed atomically by the user who minted it. An unconsumed, unexpired row is what the pane reads as an install awaiting a Slack admin.';

--
-- Name: slack_sign_ins; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.slack_sign_ins (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    state_hash text,
    nonce text NOT NULL,
    slack_team_id text NOT NULL,
    channel_id text NOT NULL,
    slack_user_id text,
    slack_user_name text,
    slack_team_name text,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT slack_sign_ins_channel_id_check CHECK ((channel_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_sign_ins_expiry_check CHECK ((expires_at > created_at)),
    CONSTRAINT slack_sign_ins_identity_check CHECK ((((slack_user_id IS NULL) = (slack_user_name IS NULL)) AND ((slack_user_id IS NULL) = (slack_team_name IS NULL)) AND ((slack_user_id IS NULL) OR (state_hash IS NULL)))),
    CONSTRAINT slack_sign_ins_nonce_check CHECK ((nonce ~ '^[A-Za-z0-9_-]{43}$'::text)),
    CONSTRAINT slack_sign_ins_slack_team_id_check CHECK ((slack_team_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_sign_ins_slack_team_name_check CHECK (((length(slack_team_name) >= 1) AND (length(slack_team_name) <= 200))),
    CONSTRAINT slack_sign_ins_slack_user_id_check CHECK ((slack_user_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_sign_ins_slack_user_name_check CHECK (((length(slack_user_name) >= 1) AND (length(slack_user_name) <= 200))),
    CONSTRAINT slack_sign_ins_state_hash_check CHECK ((state_hash ~ '^[0-9a-f]{64}$'::text))
);

ALTER TABLE public.slack_sign_ins OWNER TO postgres;

--
-- Name: TABLE slack_sign_ins; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.slack_sign_ins IS 'One Sign in with Slack attempt, bound to the ShipBash account that started it: the state''s hash until Slack''s redirect spends it, then the Slack identity the verified id_token named, until the person confirms it and the row becomes a slack_user_links row.';

--
-- Name: slack_thread_lines; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.slack_thread_lines (
    id bigint NOT NULL,
    slack_team_id text NOT NULL,
    channel_id text NOT NULL,
    thread_ts text NOT NULL,
    ts text NOT NULL,
    kind text NOT NULL,
    line jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '7 days'::interval) NOT NULL,
    CONSTRAINT slack_thread_lines_channel_id_check CHECK ((channel_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_thread_lines_kind_check CHECK ((kind = ANY (ARRAY['line'::text, 'edit'::text, 'delete'::text]))),
    CONSTRAINT slack_thread_lines_line_check CHECK ((((kind = 'delete'::text) = (line IS NULL)) AND ((line IS NULL) OR (jsonb_typeof(line) = 'object'::text)))),
    CONSTRAINT slack_thread_lines_slack_team_id_check CHECK ((slack_team_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_thread_lines_thread_ts_check CHECK ((thread_ts ~ '^[0-9]+\.[0-9]+$'::text)),
    CONSTRAINT slack_thread_lines_ts_check CHECK ((ts ~ '^[0-9]+\.[0-9]+$'::text))
);

ALTER TABLE public.slack_thread_lines OWNER TO postgres;

--
-- Name: TABLE slack_thread_lines; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.slack_thread_lines IS 'Every line Slack delivered in a channel @ShipBash is in, one row per version (line, edit, delete), kept a week, which a conversation starting mid-thread opens on.';

--
-- Name: slack_thread_lines_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.slack_thread_lines_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.slack_thread_lines_id_seq OWNER TO postgres;

--
-- Name: slack_thread_lines_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: postgres
--

ALTER SEQUENCE public.slack_thread_lines_id_seq OWNED BY public.slack_thread_lines.id;

--
-- Name: slack_thread_replies; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.slack_thread_replies (
    slack_thread_id uuid NOT NULL,
    reply_ts text NOT NULL,
    blocks jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT slack_thread_replies_blocks_check CHECK ((jsonb_typeof(blocks) = 'array'::text)),
    CONSTRAINT slack_thread_replies_reply_ts_check CHECK ((reply_ts ~ '^[0-9]+\.[0-9]+$'::text))
);

ALTER TABLE public.slack_thread_replies OWNER TO postgres;

--
-- Name: TABLE slack_thread_replies; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.slack_thread_replies IS 'A reply in a Slack conversation''s thread that carries a to-do list, with its blocks as ShipBash last set them; every draw of the list sends them back with the list swapped.';

--
-- Name: slack_thread_work; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.slack_thread_work (
    suite_run_id text,
    slack_thread_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    walk_activity_id uuid,
    title text,
    reply_ts text,
    stopped_at timestamp with time zone,
    stopped_by uuid,
    CONSTRAINT slack_thread_work_stopped_check CHECK (((stopped_by IS NULL) OR (stopped_at IS NOT NULL))),
    CONSTRAINT slack_thread_work_subject_check CHECK (((suite_run_id IS NULL) <> (walk_activity_id IS NULL))),
    CONSTRAINT slack_thread_work_title_check CHECK ((length(title) <= 200))
);

ALTER TABLE public.slack_thread_work OWNER TO postgres;

--
-- Name: TABLE slack_thread_work; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.slack_thread_work IS 'What a Slack conversation''s thread started — a verification run or a walk: its end reports to the conversation, its line rides in the to-do list under the reply that announced it (reply_ts), and the owner''s Stop on it (stopped_at, stopped_by) cancels it and silences it in Slack.';

--
-- Name: slack_threads; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.slack_threads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    project_id text NOT NULL,
    activity_id uuid NOT NULL,
    slack_team_id text NOT NULL,
    channel_id text NOT NULL,
    thread_ts text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT slack_threads_channel_id_check CHECK ((channel_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_threads_slack_team_id_check CHECK ((slack_team_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_threads_thread_ts_check CHECK ((thread_ts ~ '^[0-9]+\.[0-9]+$'::text))
);

ALTER TABLE public.slack_threads OWNER TO postgres;

--
-- Name: TABLE slack_threads; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.slack_threads IS 'A Slack thread and the conversation Activity its messages steer.';

--
-- Name: slack_user_links; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.slack_user_links (
    slack_team_id text NOT NULL,
    slack_user_id text NOT NULL,
    user_id uuid NOT NULL,
    linked_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT slack_user_links_slack_team_id_check CHECK ((slack_team_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_user_links_slack_user_id_check CHECK ((slack_user_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text))
);

ALTER TABLE public.slack_user_links OWNER TO postgres;

--
-- Name: TABLE slack_user_links; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.slack_user_links IS 'The ShipBash account a Slack user signed in as, per Slack workspace. Written only when that user confirms the identity Sign in with Slack verified for them.';

--
-- Name: slack_workspaces; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.slack_workspaces (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    slack_team_id text NOT NULL,
    slack_team_name text NOT NULL,
    icon_url text,
    bot_user_id text NOT NULL,
    bot_token_ciphertext text NOT NULL,
    encryption_key_id text NOT NULL,
    scopes text[] NOT NULL,
    connected_by uuid NOT NULL,
    connected_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    CONSTRAINT slack_workspaces_bot_token_ciphertext_check CHECK ((length(bot_token_ciphertext) > 0)),
    CONSTRAINT slack_workspaces_bot_user_id_check CHECK ((bot_user_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_workspaces_encryption_key_id_check CHECK ((encryption_key_id ~ '^[a-z0-9_-]{1,32}$'::text)),
    CONSTRAINT slack_workspaces_icon_url_check CHECK (((icon_url IS NULL) OR ((icon_url ~ '^https://[^[:space:]]+$'::text) AND (length(icon_url) <= 2048)))),
    CONSTRAINT slack_workspaces_revoked_at_check CHECK (((revoked_at IS NULL) OR (revoked_at >= connected_at))),
    CONSTRAINT slack_workspaces_scopes_check CHECK ((cardinality(scopes) > 0)),
    CONSTRAINT slack_workspaces_slack_team_id_check CHECK ((slack_team_id ~ '^[A-Z][A-Z0-9]{1,31}$'::text)),
    CONSTRAINT slack_workspaces_slack_team_name_check CHECK (((length(btrim(slack_team_name)) >= 1) AND (length(btrim(slack_team_name)) <= 200)))
);

ALTER TABLE public.slack_workspaces OWNER TO postgres;

--
-- Name: TABLE slack_workspaces; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.slack_workspaces IS 'A Slack workspace one ShipBash team has installed the app into, with the sealed bot token that install returned. revoked_at is set when Slack reports the app uninstalled or its tokens revoked; the row is kept so reconnecting restores delivery rather than rebuilding the connection.';

--
-- Name: COLUMN slack_workspaces.revoked_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.slack_workspaces.revoked_at IS 'When Slack stopped honouring this token. Null while delivery is live; cleared again by a reconnect.';

--
-- Name: suite_cases; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.suite_cases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    project_id text NOT NULL,
    suite_id uuid NOT NULL,
    "position" integer NOT NULL,
    title text NOT NULL,
    steps jsonb NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    archived_at timestamp with time zone,
    origin text NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    category text NOT NULL,
    checkpoints jsonb NOT NULL,
    why_it_matters text,
    preconditions jsonb DEFAULT '[]'::jsonb NOT NULL,
    role text DEFAULT 'journey'::text NOT NULL,
    scope_case_id uuid,
    repeat text DEFAULT 'repeatable'::text NOT NULL,
    CONSTRAINT suite_cases_category_check CHECK (((length(btrim(category)) >= 1) AND (length(btrim(category)) <= 120))),
    CONSTRAINT suite_cases_check CHECK (((archived_at IS NULL) OR (enabled = false))),
    CONSTRAINT suite_cases_checkpoints_check CHECK (shipbash_private.valid_journey_checkpoints(checkpoints)),
    CONSTRAINT suite_cases_origin_check CHECK ((origin = ANY (ARRAY['manual'::text, 'initial_discovery'::text, 'agent'::text]))),
    CONSTRAINT suite_cases_position_check CHECK (("position" >= 0)),
    CONSTRAINT suite_cases_repeat_check CHECK ((repeat = ANY (ARRAY['repeatable'::text, 'one_time'::text]))),
    CONSTRAINT suite_cases_revision_check CHECK ((revision >= 1)),
    CONSTRAINT suite_cases_role_check CHECK ((role = ANY (ARRAY['journey'::text, 'before_all'::text, 'after_all'::text, 'before_each'::text, 'after_each'::text]))),
    CONSTRAINT suite_cases_scope_role_check CHECK (((scope_case_id IS NULL) OR (role = ANY (ARRAY['before_each'::text, 'after_each'::text])))),
    CONSTRAINT suite_cases_scope_self_check CHECK ((scope_case_id IS DISTINCT FROM id)),
    CONSTRAINT suite_cases_steps_check CHECK (shipbash_private.valid_journey_steps(steps)),
    CONSTRAINT suite_cases_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 500))),
    CONSTRAINT suite_cases_why_it_matters_check CHECK (((why_it_matters IS NULL) OR ((length(btrim(why_it_matters)) >= 1) AND (length(btrim(why_it_matters)) <= 300))))
);

ALTER TABLE public.suite_cases OWNER TO postgres;

--
-- Name: COLUMN suite_cases."position"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.suite_cases."position" IS 'Visible Journey order; smaller means more important. Discovery proposals return Journeys most important first.';

--
-- Name: COLUMN suite_cases.steps; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.suite_cases.steps IS 'Ordered Journey steps as canonical [{"id", "instruction"}] entries transcribed from a real execution trajectory. Run snapshots keep the same list (suite_snapshot_cases.step_list).';

--
-- Name: COLUMN suite_cases.checkpoints; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.suite_cases.checkpoints IS 'Goal-level checkpoints as canonical {"id", "goal", "afterStep"?} entries. afterStep anchors a goal after the referenced step id in the interleaved Journey script (null before the first step; absent renders after every step); the final checkpoint states the Journey''s end outcome.';

--
-- Name: COLUMN suite_cases.why_it_matters; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.suite_cases.why_it_matters IS 'One user-facing sentence stating what breaks when this Journey breaks.';

--
-- Name: COLUMN suite_cases.role; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.suite_cases.role IS 'journey: a User Journey; before_all/after_all: a setup/teardown hook once per run; before_each/after_each: a hook around every Journey (suite-wide when scope_case_id is null, one Journey only when set).';

--
-- Name: COLUMN suite_cases.scope_case_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.suite_cases.scope_case_id IS 'The Journey a before_each/after_each hook is appended to; null means every Journey of the Suite.';

--
-- Name: COLUMN suite_cases.repeat; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.suite_cases.repeat IS 'repeatable: walked on every run; one_time: a flow that cannot be walked twice (onboarding), kept in the Suite but left out of runs.';

--
-- Name: suite_definition_revisions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.suite_definition_revisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    project_id text NOT NULL,
    suite_id uuid NOT NULL,
    revision integer NOT NULL,
    definition jsonb NOT NULL,
    source text NOT NULL,
    source_ref text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT suite_definition_revisions_definition_check CHECK (shipbash_private.valid_case_definition(definition)),
    CONSTRAINT suite_definition_revisions_revision_check CHECK ((revision >= 1)),
    CONSTRAINT suite_definition_revisions_source_check CHECK ((source = ANY (ARRAY['manual'::text, 'proposal'::text, 'initial_confirmation'::text])))
);

ALTER TABLE public.suite_definition_revisions OWNER TO postgres;

--
-- Name: suite_run_shares; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.suite_run_shares (
    run_id text NOT NULL,
    team_id uuid NOT NULL,
    is_public boolean DEFAULT false NOT NULL,
    token text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    shared_by_display_name text,
    CONSTRAINT suite_run_shares_public_token_check CHECK ((is_public = (token IS NOT NULL))),
    CONSTRAINT suite_run_shares_token_format_check CHECK (((token IS NULL) OR (token ~ '^[A-Za-z0-9_-]{43}$'::text)))
);

ALTER TABLE public.suite_run_shares OWNER TO postgres;

--
-- Name: suite_runs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.suite_runs (
    id text NOT NULL,
    project_id text NOT NULL,
    suite_snapshot_id text NOT NULL,
    mode text NOT NULL,
    source_suite_run_id text,
    status text DEFAULT 'queued'::text NOT NULL,
    verdict text,
    failure_reason text,
    lease_token uuid,
    lease_owner text,
    lease_expires_at timestamp with time zone,
    heartbeat_at timestamp with time zone,
    next_event_sequence bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    finalization_status text DEFAULT 'not_required'::text NOT NULL,
    team_id uuid,
    suite_id uuid,
    dispatch_key text,
    trigger_kind text,
    scheduled_for timestamp with time zone,
    run_units integer,
    CONSTRAINT suite_runs_check CHECK (((source_suite_run_id IS NULL) OR (source_suite_run_id <> id))),
    CONSTRAINT suite_runs_check1 CHECK (((mode <> 'case_retry'::text) OR (source_suite_run_id IS NOT NULL))),
    CONSTRAINT suite_runs_check2 CHECK ((((status = 'canceled'::text) AND (verdict = 'canceled'::text)) OR ((status = 'completed'::text) AND (verdict = ANY (ARRAY['passed'::text, 'failed'::text, 'blocked'::text, 'error'::text]))) OR ((status <> ALL (ARRAY['canceled'::text, 'completed'::text])) AND (verdict IS NULL)))),
    CONSTRAINT suite_runs_check3 CHECK (((status = ANY (ARRAY['canceled'::text, 'completed'::text])) = (completed_at IS NOT NULL))),
    CONSTRAINT suite_runs_check4 CHECK ((((lease_token IS NULL) AND (lease_owner IS NULL) AND (lease_expires_at IS NULL) AND (heartbeat_at IS NULL)) OR ((lease_token IS NOT NULL) AND (length(btrim(lease_owner)) > 0) AND (lease_expires_at IS NOT NULL) AND (heartbeat_at IS NOT NULL)))),
    CONSTRAINT suite_runs_check5 CHECK (((status <> ALL (ARRAY['canceled'::text, 'completed'::text])) OR ((lease_token IS NULL) AND (lease_owner IS NULL) AND (lease_expires_at IS NULL) AND (heartbeat_at IS NULL)))),
    CONSTRAINT suite_runs_finalization_status_check CHECK ((finalization_status = ANY (ARRAY['not_required'::text, 'pending'::text, 'finalized'::text, 'failed'::text]))),
    CONSTRAINT suite_runs_id_check CHECK ((length(btrim(id)) > 0)),
    CONSTRAINT suite_runs_mode_check CHECK ((mode = ANY (ARRAY['suite'::text, 'case_retry'::text]))),
    CONSTRAINT suite_runs_next_event_sequence_check CHECK ((next_event_sequence >= 1)),
    CONSTRAINT suite_runs_run_units_nonnegative_check CHECK ((run_units >= 0)),
    CONSTRAINT suite_runs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'waiting_for_auth'::text, 'canceling'::text, 'canceled'::text, 'completed'::text]))),
    CONSTRAINT suite_runs_trigger_kind_check CHECK (((trigger_kind IS NULL) OR (trigger_kind = ANY (ARRAY['initial_confirmation'::text, 'manual'::text, 'scheduled'::text, 'rerun'::text, 'case_retry'::text])))),
    CONSTRAINT suite_runs_verdict_check CHECK ((verdict = ANY (ARRAY['passed'::text, 'failed'::text, 'blocked'::text, 'error'::text, 'canceled'::text])))
);

ALTER TABLE public.suite_runs OWNER TO postgres;

--
-- Name: COLUMN suite_runs.finalization_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.suite_runs.finalization_status IS 'Durable Run finalization state. Runs stay pending until artifacts and auth state are durable.';

--
-- Name: COLUMN suite_runs.run_units; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.suite_runs.run_units IS 'The Runs this run counts toward its team''s monthly allowance: per Journey the runner walked, max(1, ceil(minutes / 3)) over its own walks, the before_each/after_each walks around it and an equal share of the before_all/after_all walks. Null while the run has not ended.';

--
-- Name: suite_schedules; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.suite_schedules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    project_id text NOT NULL,
    suite_id uuid NOT NULL,
    cadence text DEFAULT 'off'::text NOT NULL,
    local_time time without time zone,
    timezone text,
    next_run_at timestamp with time zone,
    last_dispatched_at timestamp with time zone,
    last_skipped_at timestamp with time zone,
    last_skip_reason text,
    updated_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    cron_expression text,
    CONSTRAINT suite_schedules_cadence_check CHECK ((cadence = ANY (ARRAY['off'::text, 'daily'::text, 'cron'::text]))),
    CONSTRAINT suite_schedules_check CHECK ((((cadence = 'off'::text) AND (local_time IS NULL) AND (timezone IS NULL) AND (next_run_at IS NULL) AND (cron_expression IS NULL)) OR ((cadence = 'daily'::text) AND (local_time IS NOT NULL) AND (length(btrim(timezone)) > 0) AND (cron_expression IS NULL)) OR ((cadence = 'cron'::text) AND (length(btrim(cron_expression)) > 0) AND (length(btrim(timezone)) > 0) AND (local_time IS NULL))))
);

ALTER TABLE public.suite_schedules OWNER TO postgres;

--
-- Name: suite_snapshot_cases; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.suite_snapshot_cases (
    id text NOT NULL,
    snapshot_id text NOT NULL,
    "position" smallint NOT NULL,
    title text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    team_id uuid,
    suite_case_id uuid,
    suite_case_revision integer,
    category text NOT NULL,
    checkpoints jsonb NOT NULL,
    preconditions jsonb DEFAULT '[]'::jsonb NOT NULL,
    role text DEFAULT 'journey'::text NOT NULL,
    scope_suite_case_id uuid,
    repeat text DEFAULT 'repeatable'::text NOT NULL,
    step_list jsonb NOT NULL,
    CONSTRAINT suite_snapshot_cases_category_check CHECK (((length(btrim(category)) >= 1) AND (length(btrim(category)) <= 120))),
    CONSTRAINT suite_snapshot_cases_checkpoints_check CHECK (shipbash_private.valid_journey_checkpoints(checkpoints)),
    CONSTRAINT suite_snapshot_cases_id_check CHECK ((length(btrim(id)) > 0)),
    CONSTRAINT suite_snapshot_cases_position_nonnegative_check CHECK (("position" >= 0)),
    CONSTRAINT suite_snapshot_cases_repeat_check CHECK ((repeat = ANY (ARRAY['repeatable'::text, 'one_time'::text]))),
    CONSTRAINT suite_snapshot_cases_role_check CHECK ((role = ANY (ARRAY['journey'::text, 'before_all'::text, 'after_all'::text, 'before_each'::text, 'after_each'::text]))),
    CONSTRAINT suite_snapshot_cases_scope_role_check CHECK (((scope_suite_case_id IS NULL) OR (role = ANY (ARRAY['before_each'::text, 'after_each'::text])))),
    CONSTRAINT suite_snapshot_cases_step_list_check CHECK (shipbash_private.valid_journey_steps(step_list)),
    CONSTRAINT suite_snapshot_cases_suite_case_revision_check CHECK (((suite_case_revision IS NULL) OR (suite_case_revision >= 1))),
    CONSTRAINT suite_snapshot_cases_title_check CHECK ((length(btrim(title)) > 0))
);

ALTER TABLE public.suite_snapshot_cases OWNER TO postgres;

--
-- Name: COLUMN suite_snapshot_cases.scope_suite_case_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.suite_snapshot_cases.scope_suite_case_id IS 'The suite_cases id of the Journey a before_each/after_each hook is appended to, frozen with the row; the run input resolves it to the sibling snapshot Case.';

--
-- Name: COLUMN suite_snapshot_cases.step_list; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.suite_snapshot_cases.step_list IS 'The Case''s steps as the run walks them, the [{"id", "instruction"}] list of suite_cases.steps at snapshot time.';

--
-- Name: suite_snapshots; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.suite_snapshots (
    id text NOT NULL,
    project_id text NOT NULL,
    production_url text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    team_id uuid,
    suite_id uuid,
    definition_revision_id uuid,
    auth_profile_id text,
    auth_profile_state_version text,
    repository_id uuid,
    repository_commit_sha text,
    testing_context text,
    prompt_contract_versions jsonb DEFAULT '{}'::jsonb NOT NULL,
    model_contract jsonb DEFAULT '{}'::jsonb NOT NULL,
    trigger_identity jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT suite_snapshots_id_check CHECK ((length(btrim(id)) > 0)),
    CONSTRAINT suite_snapshots_model_contract_check CHECK ((jsonb_typeof(model_contract) = 'object'::text)),
    CONSTRAINT suite_snapshots_production_url_check CHECK ((length(btrim(production_url)) > 0)),
    CONSTRAINT suite_snapshots_prompt_contract_versions_check CHECK ((jsonb_typeof(prompt_contract_versions) = 'object'::text)),
    CONSTRAINT suite_snapshots_repository_commit_sha_check CHECK (((repository_commit_sha IS NULL) OR (repository_commit_sha ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT suite_snapshots_testing_context_check CHECK (((testing_context IS NULL) OR (length(testing_context) <= 20000))),
    CONSTRAINT suite_snapshots_trigger_identity_check CHECK ((jsonb_typeof(trigger_identity) = 'object'::text))
);

ALTER TABLE public.suite_snapshots OWNER TO postgres;

--
-- Name: suites; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.suites (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    project_id text NOT NULL,
    name text NOT NULL,
    definition_revision integer DEFAULT 0 NOT NULL,
    lifecycle_status text DEFAULT 'active'::text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    product_thesis text,
    CONSTRAINT suites_definition_revision_check CHECK ((definition_revision >= 0)),
    CONSTRAINT suites_lifecycle_status_check CHECK ((lifecycle_status = ANY (ARRAY['active'::text, 'archived'::text]))),
    CONSTRAINT suites_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200))),
    CONSTRAINT suites_product_thesis_check CHECK (((product_thesis IS NULL) OR ((length(btrim(product_thesis)) >= 1) AND (length(btrim(product_thesis)) <= 600))))
);

ALTER TABLE public.suites OWNER TO postgres;

--
-- Name: COLUMN suites.product_thesis; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.suites.product_thesis IS 'Discovery product thesis: what the product is, its core value actions, and its funnel (at most 600 characters).';

--
-- Name: target_auth_handoffs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.target_auth_handoffs (
    project_id text NOT NULL,
    team_id uuid NOT NULL,
    target_kind text NOT NULL,
    target_id text NOT NULL,
    sandbox_name text,
    command_id text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT target_auth_handoffs_command_id_check CHECK (((command_id IS NULL) OR (length(btrim(command_id)) > 0))),
    CONSTRAINT target_auth_handoffs_sandbox_name_check CHECK (((sandbox_name IS NULL) OR (sandbox_name ~ '^shipbash-handoff-[0-9a-f]{16}-[0-9a-f]{8}$'::text))),
    CONSTRAINT target_auth_handoffs_target_id_check CHECK ((length(btrim(target_id)) > 0)),
    CONSTRAINT target_auth_handoffs_target_kind_check CHECK ((target_kind = ANY (ARRAY['run'::text, 'activity'::text]))),
    CONSTRAINT target_auth_handoffs_viewer_check CHECK (((sandbox_name IS NULL) = (command_id IS NULL)))
);

ALTER TABLE public.target_auth_handoffs OWNER TO postgres;

--
-- Name: TABLE target_auth_handoffs; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.target_auth_handoffs IS 'The one product sign-in handoff a Project can run at a time: the run or Activity waiting on it, and once its viewer is up, the Sandbox and command showing it. Service role only.';

--
-- Name: target_auth_profiles; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.target_auth_profiles (
    id text NOT NULL,
    project_id text NOT NULL,
    production_origin text NOT NULL,
    status text DEFAULT 'missing'::text NOT NULL,
    profile_locator text NOT NULL,
    state_locator text NOT NULL,
    state_version text,
    last_verified_at timestamp with time zone,
    failure_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    team_id uuid,
    state_ciphertext text,
    encryption_key_id text,
    state_updated_at timestamp with time zone,
    CONSTRAINT target_auth_profiles_check CHECK (((status <> 'ready'::text) OR ((state_version IS NOT NULL) AND (last_verified_at IS NOT NULL)))),
    CONSTRAINT target_auth_profiles_encryption_key_id_check CHECK (((encryption_key_id IS NULL) OR (encryption_key_id ~ '^[a-z0-9_-]{1,32}$'::text))),
    CONSTRAINT target_auth_profiles_encryption_key_present_check CHECK (((state_ciphertext IS NULL) OR (encryption_key_id IS NOT NULL))),
    CONSTRAINT target_auth_profiles_id_check CHECK ((length(btrim(id)) > 0)),
    CONSTRAINT target_auth_profiles_production_origin_check CHECK ((length(btrim(production_origin)) > 0)),
    CONSTRAINT target_auth_profiles_profile_locator_check CHECK ((length(btrim(profile_locator)) > 0)),
    CONSTRAINT target_auth_profiles_state_locator_check CHECK ((length(btrim(state_locator)) > 0)),
    CONSTRAINT target_auth_profiles_state_updated_check CHECK (((state_ciphertext IS NULL) = (state_updated_at IS NULL))),
    CONSTRAINT target_auth_profiles_status_check CHECK ((status = ANY (ARRAY['missing'::text, 'verifying'::text, 'ready'::text, 'expired'::text, 'failed'::text])))
);

ALTER TABLE public.target_auth_profiles OWNER TO postgres;

--
-- Name: TABLE target_auth_profiles; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.target_auth_profiles IS 'The tested product login state: its health metadata, and the browser state itself, application-sealed. Tasks receive the state at launch.';

--
-- Name: COLUMN target_auth_profiles.state_ciphertext; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.target_auth_profiles.state_ciphertext IS 'Application-sealed browser sign-in state envelope (agent-browser state JSON). Never exposed through the Data API.';

--
-- Name: COLUMN target_auth_profiles.encryption_key_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.target_auth_profiles.encryption_key_id IS 'Name of the environment key that sealed this row. Readable by members so a key the deployment has lost reads as a paused sign-in; the key material itself never leaves the environment.';

--
-- Name: COLUMN target_auth_profiles.state_updated_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.target_auth_profiles.state_updated_at IS 'When the sealed state was last written: at the sign-in handoff that captured it.';

--
-- Name: team_access_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.team_access_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    requested_by uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT team_access_requests_decision_check CHECK ((((status = 'pending'::text) AND (decided_by IS NULL) AND (decided_at IS NULL)) OR ((status = ANY (ARRAY['approved'::text, 'declined'::text])) AND (decided_by IS NOT NULL) AND (decided_at IS NOT NULL)))),
    CONSTRAINT team_access_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'declined'::text])))
);

ALTER TABLE public.team_access_requests OWNER TO postgres;

--
-- Name: team_invitations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.team_invitations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    invited_github_user_id bigint NOT NULL,
    invited_github_login text NOT NULL,
    token_hash text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    created_by uuid NOT NULL,
    accepted_by uuid,
    expires_at timestamp with time zone NOT NULL,
    accepted_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT team_invitations_check CHECK ((expires_at > created_at)),
    CONSTRAINT team_invitations_check1 CHECK ((((status = 'pending'::text) AND (accepted_by IS NULL) AND (accepted_at IS NULL) AND (revoked_at IS NULL)) OR ((status = 'accepted'::text) AND (accepted_by IS NOT NULL) AND (accepted_at IS NOT NULL) AND (revoked_at IS NULL)) OR ((status = 'revoked'::text) AND (accepted_by IS NULL) AND (accepted_at IS NULL) AND (revoked_at IS NOT NULL)))),
    CONSTRAINT team_invitations_invited_github_login_check CHECK (((length(btrim(invited_github_login)) >= 1) AND (length(btrim(invited_github_login)) <= 100))),
    CONSTRAINT team_invitations_invited_github_user_id_check CHECK ((invited_github_user_id > 0)),
    CONSTRAINT team_invitations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'revoked'::text]))),
    CONSTRAINT team_invitations_token_hash_check CHECK ((token_hash ~ '^[0-9a-f]{64}$'::text))
);

ALTER TABLE public.team_invitations OWNER TO postgres;

--
-- Name: team_memberships; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.team_memberships (
    team_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT team_memberships_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'member'::text])))
);

ALTER TABLE public.team_memberships OWNER TO postgres;

--
-- Name: team_sign_in_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.team_sign_in_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    sign_in_id uuid NOT NULL,
    project_id text,
    actor text NOT NULL,
    actor_user_id uuid,
    action text NOT NULL,
    outcome text,
    at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT team_sign_in_events_action_check CHECK ((action = ANY (ARRAY['saved'::text, 'updated'::text, 'removed'::text, 'verify_started'::text, 'verify_succeeded'::text, 'verify_failed'::text, 'paused'::text, 'resumed'::text, 'auto_sign_in'::text]))),
    CONSTRAINT team_sign_in_events_actor_check CHECK ((actor = ANY (ARRAY['user'::text, 'verification_leg'::text, 'auto_login_leg'::text]))),
    CONSTRAINT team_sign_in_events_actor_user_check CHECK (((actor <> 'user'::text) OR (actor_user_id IS NOT NULL))),
    CONSTRAINT team_sign_in_events_outcome_check CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['wrong_credentials'::text, 'second_factor_required'::text, 'captcha_required'::text, 'login_page_not_found'::text, 'session_expired'::text, 'sso_enforced'::text, 'new_device_verification'::text, 'unknown'::text]))))
);

ALTER TABLE public.team_sign_in_events OWNER TO postgres;

--
-- Name: TABLE team_sign_in_events; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.team_sign_in_events IS 'Audit trail for Team sign-ins. No column here ever holds a credential or a session value.';

--
-- Name: team_sign_ins; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.team_sign_ins (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    method text NOT NULL,
    label text,
    login_url text,
    status text DEFAULT 'unverified'::text NOT NULL,
    failure_reason text,
    consecutive_failures integer DEFAULT 0 NOT NULL,
    credential_ciphertext text,
    session_ciphertext text,
    session_version text,
    encryption_key_id text,
    last_verified_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    github_account_login text,
    CONSTRAINT team_sign_ins_consecutive_failures_check CHECK ((consecutive_failures >= 0)),
    CONSTRAINT team_sign_ins_credential_check CHECK (((status = 'revoked'::text) OR (method <> 'email_password'::text) OR (credential_ciphertext IS NOT NULL))),
    CONSTRAINT team_sign_ins_encryption_key_id_check CHECK (((encryption_key_id IS NULL) OR (encryption_key_id ~ '^[a-z0-9_-]{1,32}$'::text))),
    CONSTRAINT team_sign_ins_encryption_key_present_check CHECK ((((credential_ciphertext IS NULL) AND (session_ciphertext IS NULL)) OR (encryption_key_id IS NOT NULL))),
    CONSTRAINT team_sign_ins_failure_reason_check CHECK (((failure_reason IS NULL) OR (failure_reason = ANY (ARRAY['wrong_credentials'::text, 'second_factor_required'::text, 'captcha_required'::text, 'login_page_not_found'::text, 'session_expired'::text, 'sso_enforced'::text, 'new_device_verification'::text, 'unknown'::text])))),
    CONSTRAINT team_sign_ins_github_account_login_check CHECK ((github_account_login ~ '^[a-zA-Z0-9][a-zA-Z0-9-]{0,38}$'::text)),
    CONSTRAINT team_sign_ins_label_check CHECK (((label IS NULL) OR ((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 200)))),
    CONSTRAINT team_sign_ins_login_url_check CHECK (((login_url IS NULL) OR ((length(btrim(login_url)) >= 1) AND (length(btrim(login_url)) <= 2000)))),
    CONSTRAINT team_sign_ins_method_check CHECK ((method = ANY (ARRAY['google'::text, 'github'::text, 'apple'::text, 'sso'::text, 'phone_code'::text, 'magic_link'::text, 'any_login_page'::text, 'email_password'::text]))),
    CONSTRAINT team_sign_ins_paused_check CHECK (((status <> 'paused'::text) OR (consecutive_failures >= 3))),
    CONSTRAINT team_sign_ins_ready_check CHECK (((status <> 'ready'::text) OR ((session_version IS NOT NULL) AND (last_verified_at IS NOT NULL)))),
    CONSTRAINT team_sign_ins_session_version_check CHECK (((session_version IS NULL) OR (session_version ~ '^authv_[0-9a-f]{16}$'::text))),
    CONSTRAINT team_sign_ins_status_check CHECK ((status = ANY (ARRAY['unverified'::text, 'verifying'::text, 'ready'::text, 'failed'::text, 'paused'::text, 'revoked'::text])))
);

ALTER TABLE public.team_sign_ins OWNER TO postgres;

--
-- Name: TABLE team_sign_ins; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.team_sign_ins IS 'One way into the tested product, saved for the whole Team. Secret material is sealed by the application before it reaches this table.';

--
-- Name: COLUMN team_sign_ins.label; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.team_sign_ins.label IS 'Account identity read back by the verification leg, never typed by a person. Null when the signed-in product names nobody, which does not stop the leg ticking the sign-in.';

--
-- Name: COLUMN team_sign_ins.credential_ciphertext; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.team_sign_ins.credential_ciphertext IS 'Application-sealed credential envelope. Never exposed through the Data API.';

--
-- Name: COLUMN team_sign_ins.session_ciphertext; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.team_sign_ins.session_ciphertext IS 'Application-sealed captured browser session. Never exposed through the Data API.';

--
-- Name: COLUMN team_sign_ins.session_version; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.team_sign_ins.session_version IS 'Fingerprint of the captured session. Never exposed through the Data API.';

--
-- Name: COLUMN team_sign_ins.encryption_key_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.team_sign_ins.encryption_key_id IS 'Name of the environment key that sealed this row. Readable by members so a key the deployment has lost reads as a paused sign-in; the key material itself never leaves the environment.';

--
-- Name: teams; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.teams (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    slug text NOT NULL,
    workspace_domain text,
    monthly_run_quota integer DEFAULT 60,
    CONSTRAINT teams_monthly_run_quota_check CHECK ((monthly_run_quota >= 0)),
    CONSTRAINT teams_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 120))),
    CONSTRAINT teams_workspace_domain_check CHECK ((workspace_domain ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$'::text))
);

ALTER TABLE public.teams OWNER TO postgres;

--
-- Name: COLUMN teams.workspace_domain; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.teams.workspace_domain IS 'The Google Workspace domain this team is the company team of; null for every team made by hand. One team per domain.';

--
-- Name: COLUMN teams.monthly_run_quota; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.teams.monthly_run_quota IS 'The Runs this team''s verification runs may count per UTC calendar month before a new one is refused; null is no limit.';

--
-- Name: user_profiles; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.user_profiles (
    user_id uuid NOT NULL,
    display_name text NOT NULL,
    github_user_id bigint,
    github_login text,
    avatar_url text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    email text,
    workspace_domain text,
    default_team_id uuid,
    CONSTRAINT user_profiles_display_name_check CHECK (((length(btrim(display_name)) >= 1) AND (length(btrim(display_name)) <= 120))),
    CONSTRAINT user_profiles_email_check CHECK (((length(email) >= 3) AND (length(email) <= 320))),
    CONSTRAINT user_profiles_github_identity_check CHECK (((github_user_id IS NULL) = (github_login IS NULL))),
    CONSTRAINT user_profiles_github_login_check CHECK (((length(btrim(github_login)) >= 1) AND (length(btrim(github_login)) <= 100))),
    CONSTRAINT user_profiles_github_user_id_check CHECK ((github_user_id > 0)),
    CONSTRAINT user_profiles_workspace_domain_check CHECK ((workspace_domain ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$'::text))
);

ALTER TABLE public.user_profiles OWNER TO postgres;

--
-- Name: COLUMN user_profiles.email; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.user_profiles.email IS 'How teammates know an account without a GitHub login: its email. Null for an account with one, whose login names it.';

--
-- Name: COLUMN user_profiles.workspace_domain; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.user_profiles.workspace_domain IS 'The Google Workspace domain (`hd`) of the account''s Google identity; null for a personal Google account or none.';

--
