reset check_function_bodies;

--
-- Privileges
--
-- pg_dump writes each object's privileges as changes from PostgreSQL's
-- built-in default: the owner only, plus EXECUTE for PUBLIC on functions.
-- Supabase's default privileges also grant anon, authenticated and
-- service_role on every object created above, so those grants are revoked
-- first; the statements after them then give each object its exact privileges.
--

revoke all on all tables in schema public, shipbash_private from anon, authenticated, service_role;
revoke all on all sequences in schema public, shipbash_private from anon, authenticated, service_role;
revoke all on all functions in schema public, shipbash_private from anon, authenticated, service_role;

--
-- Name: SCHEMA shipbash_private; Type: ACL; Schema: -; Owner: postgres
--

GRANT USAGE ON SCHEMA shipbash_private TO authenticated;
GRANT USAGE ON SCHEMA shipbash_private TO service_role;

--
-- Name: FUNCTION accept_team_invitation(invitation_token_hash text); Type: ACL; Schema: shipbash_private; Owner: postgres
--

REVOKE ALL ON FUNCTION shipbash_private.accept_team_invitation(invitation_token_hash text) FROM PUBLIC;
GRANT ALL ON FUNCTION shipbash_private.accept_team_invitation(invitation_token_hash text) TO authenticated;
GRANT ALL ON FUNCTION shipbash_private.accept_team_invitation(invitation_token_hash text) TO service_role;

--
-- Name: FUNCTION bootstrap_current_user(display_name_override text); Type: ACL; Schema: shipbash_private; Owner: postgres
