REVOKE ALL ON FUNCTION shipbash_private.bootstrap_current_user(display_name_override text) FROM PUBLIC;
GRANT ALL ON FUNCTION shipbash_private.bootstrap_current_user(display_name_override text) TO authenticated;
GRANT ALL ON FUNCTION shipbash_private.bootstrap_current_user(display_name_override text) TO service_role;

