REVOKE ALL ON FUNCTION shipbash_private.can_view_profile(target_user_id uuid) FROM PUBLIC;
GRANT ALL ON FUNCTION shipbash_private.can_view_profile(target_user_id uuid) TO authenticated;
GRANT ALL ON FUNCTION shipbash_private.can_view_profile(target_user_id uuid) TO service_role;

