--
-- Storage buckets
--

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('shipbash-browser-recordings', 'shipbash-browser-recordings', false, 268435456, '{video/mp4,image/jpeg}'::text[])
on conflict (id) do update
set name = excluded.name,
    public = excluded.public,
    file_size_limit = excluded.file_size_limit,
    allowed_mime_types = excluded.allowed_mime_types;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('shipbash-run-artifacts', 'shipbash-run-artifacts', false, 104857600, '{image/png,image/jpeg,image/webp,video/mp4,application/json,application/gzip,application/zip,text/plain,application/octet-stream}'::text[])
on conflict (id) do update
set name = excluded.name,
    public = excluded.public,
    file_size_limit = excluded.file_size_limit,
    allowed_mime_types = excluded.allowed_mime_types;

